/**
 * @file _components/code/code-panel.tsx
 * @description Code viewer panel — file explorer on top, code display below.
 *
 * Shows the files generated by the AI agent. Files are read-only (Phase 1).
 * When the agent is actively writing, newly written files are highlighted.
 * Includes a "Download ZIP" button to save all files locally.
 */

"use client";

import { useMemo, useCallback, useState } from "react";
import { FileExplorer } from "./file-explorer";
import { CodeDisplay } from "./code-display";
import { NoFilesPlaceholder } from "./no-files-placeholder";
import { Button } from "@/components/ui/button";
import { Download, Loader2 } from "lucide-react";
import { toast } from "sonner";
import type { WorkspacePhase } from "@/hooks/use-workspace-state";

interface CodePanelProps {
  /** Map of file paths → file contents from Fragment.files */
  files: Record<string, string>;
  /** Paths of files recently written by the agent (from SSE). */
  writtenFiles: string[];
  /** Currently selected file path. */
  selectedFile: string | null;
  /** Callback when user selects a file in the explorer. */
  onSelectFile: (path: string | null) => void;
  /** Current agent phase. */
  phase: WorkspacePhase;
}

export function CodePanel({
  files,
  writtenFiles,
  selectedFile,
  onSelectFile,
  phase,
}: CodePanelProps) {
  const filePaths = useMemo(() => Object.keys(files).sort(), [files]);
  const [isDownloading, setIsDownloading] = useState(false);

  // Auto-select the first file if none is selected
  const activeFile = selectedFile ?? filePaths[0] ?? null;

  // Detect language from file extension
  const language = useMemo(() => {
    if (!activeFile) return "tsx";
    const ext = activeFile.split(".").pop()?.toLowerCase();
    const langMap: Record<string, string> = {
      tsx: "tsx",
      ts: "typescript",
      jsx: "jsx",
      js: "javascript",
      css: "css",
      json: "json",
      html: "html",
      md: "markdown",
      prisma: "prisma",
      sql: "sql",
      sh: "bash",
      yaml: "yaml",
      yml: "yaml",
      toml: "toml",
      env: "bash",
    };
    return langMap[ext ?? ""] ?? "plaintext";
  }, [activeFile]);

  /** Download all files as a ZIP archive. */
  const handleDownloadZip = useCallback(async () => {
    if (filePaths.length === 0) return;
    setIsDownloading(true);
    try {
      const JSZip = (await import("jszip")).default;
      const zip = new JSZip();
      for (const [path, content] of Object.entries(files)) {
        zip.file(path, content);
      }
      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "project-files.zip";
      a.click();
      URL.revokeObjectURL(url);
      toast.success(`Downloaded ${filePaths.length} files as ZIP`);
    } catch {
      toast.error("Failed to create ZIP file");
    } finally {
      setIsDownloading(false);
    }
  }, [files, filePaths.length]);

  if (filePaths.length === 0) {
    return <NoFilesPlaceholder phase={phase} />;
  }

  return (
    <div className="flex h-full flex-col bg-background border-x">
      {/* Header with file count and download button */}
      <div className="flex items-center justify-between border-b px-3 py-1.5">
        <span className="text-xs text-muted-foreground font-medium">
          {filePaths.length} file{filePaths.length !== 1 ? "s" : ""}
        </span>
        <Button
          variant="ghost"
          size="sm"
          className="h-7 gap-1.5 text-xs"
          onClick={handleDownloadZip}
          disabled={isDownloading}
        >
          {isDownloading ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Download className="h-3.5 w-3.5" />
          )}
          Download ZIP
        </Button>
      </div>

      {/* File explorer (collapsible tree) */}
      <FileExplorer
        filePaths={filePaths}
        writtenFiles={writtenFiles}
        selectedFile={activeFile}
        onSelectFile={onSelectFile}
      />

      {/* Code display */}
      <div className="flex-1 overflow-hidden">
        {activeFile && files[activeFile] ? (
          <CodeDisplay
            code={files[activeFile]}
            filePath={activeFile}
            language={language}
          />
        ) : (
          <div className="flex items-center justify-center h-full text-sm text-muted-foreground">
            Select a file to view its contents
          </div>
        )}
      </div>
    </div>
  );
}
